/*!
 * Apollo Icons Runtime  v1.0.3
 * Inline SVG renderer — CDN-fetched, mask-free, sprite-free, FA-free.
 * Approx. ~3 KB gzipped.
 *
 * Class resolution preserved:
 *   ri-home-fill  → home-s    ri-home-line  → home-v
 *   i-home-fill   → home-s    i-home-line   → home-v
 *   i-home-s      → home-s    i-home-v      → home-v
 *   icon-home-s   → home-s    data-icon="home-fill" → home-s
 */
"use strict";
(function (win) {
  if (win.__apolloIconRuntime) return;
  win.__apolloIconRuntime = 1;

  var doc = win.document;
  var cfg = win.apolloIconConfig || {};
  var CDN = (cfg.cdn || "https://assets.apollo.rio.br").replace(/\/+$/, "");
  var PATH = cfg.iconPath || "/i/";
  var DBG = !!cfg.debug;

  function remoteFetchAllowed() {
    if (cfg.remoteFetch === false) return false;
    if (cfg.remoteFetch === true) return true;
    try {
      var h = (win.location.hostname || "").toLowerCase();
      if (!h) return false;
      if (h === "localhost" || h === "127.0.0.1" || /\.local$/.test(h)) {
        return true;
      }
      return (
        h === "apollo.rio.br" ||
        h.slice(-14) === ".apollo.rio.br" ||
        h === "cdn.apollo.rio.br" ||
        h === "assets.apollo.rio.br"
      );
    } catch (e) {
      return false;
    }
  }

  var REMOTE_FETCH = remoteFetchAllowed();

  /* ── Caches ──────────────────────────────────────────────────────────── */
  var svgCache = new Map(); // canonical → SVG text (empty string = not found)
  var inflight = new Map(); // canonical → Promise<string>
  var applied = new WeakMap(); // el → last applied canonical name

  /* ── Utils ───────────────────────────────────────────────────────────── */
  function log() {
    if (DBG)
      console.log.apply(
        console,
        ["[ApolloIcons]"].concat([].slice.call(arguments)),
      );
  }

  function iconUrl(name) {
    return CDN + PATH + name + ".svg";
  }

  /* ── normalize ───────────────────────────────────────────────────────── *
   * Converts any raw name / class fragment to canonical form:
   *   "home-fill" | "home-solid"            → "home-s"
   *   "home-line" | "home-outline"          → "home-v"
   *   "home-s"                              → "home-s"
   *   "home-v"                              → "home-v"
   *   "home"  (with fallback="-s")          → "home-s"
   *   "home"  (with fallback="-v")          → "home-v"
   * ─────────────────────────────────────────────────────────────────────── */
  function normalize(raw, fallback) {
    if (!raw) return "";
    var s = String(raw)
      .toLowerCase()
      .trim()
      .replace(/[^a-z0-9\-_]+/g, "-");
    if (!s) return "";

    var suffix;
    if (s.endsWith("-fill") || s.endsWith("-solid")) {
      suffix = "-s";
      s = s.slice(0, s.lastIndexOf("-"));
    } else if (
      s.endsWith("-line") ||
      s.endsWith("-outline") ||
      s.endsWith("-vector")
    ) {
      suffix = "-v";
      s = s.slice(0, s.lastIndexOf("-"));
    } else if (s.endsWith("-s")) {
      suffix = "-s";
      s = s.slice(0, -2);
    } else if (s.endsWith("-v")) {
      suffix = "-v";
      s = s.slice(0, -2);
    } else {
      suffix = fallback || "-v";
    }

    /* strip double-dashes and leading/trailing separators */
    s = s.replace(/-{2,}/g, "-").replace(/^[-_]+|[-_]+$/g, "");
    if (!s || !/^[a-z0-9][a-z0-9\-_]*$/.test(s)) return "";
    return s + suffix;
  }

  /* ── resolve ─────────────────────────────────────────────────────────── *
   * Resolves an element's canonical icon name in priority order:
   *   1. ri-*       (RemixIcon prefix  — bare names default to -v)
   *   2. i-*        (Apollo native      — bare names default to -s)
   *   3. icon-*     (generic prefix     — bare names default to -v)
   *   4. data-icon  (attribute fallback — bare names default to -v)
   * ─────────────────────────────────────────────────────────────────────── */
  function resolve(el) {
    var cl = el.classList;
    var c, n, r;

    if (cl && cl.length) {
      /* 1 — RemixIcon (ri-) */
      for (var i = 0; i < cl.length; i++) {
        c = String(cl[i]).toLowerCase();
        if (c.indexOf("ri-") === 0) {
          r = normalize(c.slice(3), "-v");
          if (r) return r;
        }
      }

      /* 2 — Apollo native (i-), skip size and animation utility classes */
      for (var i = 0; i < cl.length; i++) {
        c = String(cl[i]).toLowerCase();
        if (
          c.indexOf("i-") === 0 &&
          !/^i-\d+(\.\d+)?x$/.test(c) &&
          !/^i-(beat|fade|beat-fade|bounce|flip|shake|spin|spin-pulse|spin-reverse|solid|regular)$/.test(
            c,
          )
        ) {
          n = c.slice(2);
          if (!n) continue;
          r = normalize(n, "-s");
          if (r) return r;
        }
      }

      /* 3 — Generic (icon-) */
      for (var i = 0; i < cl.length; i++) {
        c = String(cl[i]).toLowerCase();
        if (c.indexOf("icon-") === 0) {
          r = normalize(c.slice(5), "-v");
          if (r) return r;
        }
      }
    }

    /* 4 — data-icon attribute */
    var d = el.getAttribute("data-icon");
    if (d) {
      r = normalize(d.toLowerCase(), "-v");
      if (r) return r;
    }

    return "";
  }

  /* ── fetchSVG ────────────────────────────────────────────────────────── *
   * Fetches SVG text from CDN with in-flight deduplication.
   * On success: stored as string in svgCache.
   * On failure: stored as "" in svgCache (no retry noise).
   * ─────────────────────────────────────────────────────────────────────── */
  function fetchSVG(name) {
    if (!REMOTE_FETCH) return Promise.resolve("");
    if (svgCache.has(name)) return Promise.resolve(svgCache.get(name));
    if (inflight.has(name)) return inflight.get(name);

    var p = win
      .fetch(iconUrl(name), { mode: "cors", credentials: "omit" })
      .then(function (r) {
        return r.ok ? r.text() : "";
      })
      .catch(function () {
        return "";
      })
      .then(function (text) {
        svgCache.set(name, text);
        inflight.delete(name);
        return text;
      });

    inflight.set(name, p);
    return p;
  }

  /* ── createIcon ──────────────────────────────────────────────────────── *
   * Parses SVG text and returns a clean <svg> element:
   *   - Removes width / height attributes (scaled by font-size / 1em)
   *   - Adds shape-rendering: geometricPrecision
   *   - Adds vector-effect:   non-scaling-stroke
   *   - Hides from screen readers (aria-hidden)
   *   - Hard-codes fill: currentColor so it inherits text colour
   *   - DOM-level cache: parse once, cloneNode(true) for repeats
   * ─────────────────────────────────────────────────────────────────────── */
  var domCache = new Map(); // svgText → clean SVG element (template)

  function createIcon(svgText) {
    if (!svgText) return null;
    var cached = domCache.get(svgText);
    if (cached) return cached.cloneNode(true);

    var tmp = doc.createElement("span");
    tmp.innerHTML = svgText;
    var svg = tmp.querySelector("svg");
    if (!svg) return null;

    svg.removeAttribute("width");
    svg.removeAttribute("height");
    svg.setAttribute("shape-rendering", "geometricPrecision");
    svg.setAttribute("vector-effect", "non-scaling-stroke");
    svg.setAttribute("aria-hidden", "true");
    svg.style.cssText =
      "width:1em;height:1em;display:inline-block;" +
      "vertical-align:-.125em;fill:currentColor;overflow:visible;";

    domCache.set(svgText, svg);
    return svg.cloneNode(true);
  }

  /* ── upgradeIcon ─────────────────────────────────────────────────────── *
   * Resolves the icon name for an element, fetches the SVG, and renders it.
   * Skips if the same name is already rendered (idempotent).
   * Handles late-arriving responses: stale token check prevents clobbering.
   * ─────────────────────────────────────────────────────────────────────── */
  function upgradeIcon(el) {
    if (!el || el.nodeType !== 1) return;
    var name = resolve(el);
    if (!name || applied.get(el) === name) return;
    applied.set(el, name);

    fetchSVG(name).then(function (text) {
      /* abort if element's icon changed while we were fetching */
      if (applied.get(el) !== name) return;
      var svg = createIcon(text);
      if (!svg) return;

      el.textContent = "";
      el.setAttribute("data-apollo-icon", name);
      el.style.display = el.style.display || "inline-block";
      el.appendChild(svg);
      log("rendered", name);
    });
  }

  /* ── upgradeAllIcons ─────────────────────────────────────────────────── *
   * Scans a root node (defaults to document) and upgrades every icon element.
   * ─────────────────────────────────────────────────────────────────────── */
  var SELECTOR =
    "[data-icon],[data-apollo-icon]," +
    '[class*="ri-"],' +
    '[class^="i-"],[class*=" i-"],' +
    '[class^="icon-"],[class*=" icon-"]';

  function upgradeAllIcons(root) {
    if (!root) return;
    try {
      if (root.nodeType === 1 && isIconEl(root)) upgradeIcon(root);
      if (root.querySelectorAll) {
        var els = root.querySelectorAll(SELECTOR);
        for (var i = 0; i < els.length; i++) upgradeIcon(els[i]);
      }
    } catch (e) {
      /* ignore stale removals */
    }
  }

  function isIconEl(el) {
    if (!el || el.nodeType !== 1) return false;
    if (el.hasAttribute("data-icon") || el.hasAttribute("data-apollo-icon"))
      return true;
    var cl = el.classList;
    if (!cl) return false;
    for (var i = 0; i < cl.length; i++) {
      var c = String(cl[i]).toLowerCase();
      if (
        c.indexOf("ri-") === 0 ||
        c.indexOf("i-") === 0 ||
        c.indexOf("icon-") === 0
      )
        return true;
    }
    return false;
  }

  /* ── injectCSS ───────────────────────────────────────────────────────── *
   * Injects the minimum CSS needed for host elements (display, sizing).
   * The actual SVG handles its own size via 1em × 1em inline styles.
   * ─────────────────────────────────────────────────────────────────────── */
  function injectCSS() {
    if (doc.getElementById("apollo-icon-css")) return;
    var s = "";
    /* host element base display — covers ri-*, i-*, icon-* and upgraded elements */
    s += "[data-apollo-icon],";
    s += '[class*="ri-"],[class^="i-"],[class*=" i-"],';
    s += '[class^="icon-"],[class*=" icon-"]{';
    s += "display:inline-block;line-height:1;vertical-align:-.125em;}";
    /* all SVGs inside inherit text colour */
    s += "[data-apollo-icon] svg{fill:currentColor;}";
    /* suppress RemixIcon font glyphs (::before) the instant SVG is rendered —
       data-apollo-icon is set synchronously before appendChild, so no frame
       ever shows both the font glyph and the SVG simultaneously */
    s +=
      "[data-apollo-icon]::before,[data-apollo-icon]::after{content:none!important;display:none!important;}";

    var el = doc.createElement("style");
    el.id = "apollo-icon-css";
    el.textContent = s;
    var h = doc.head || doc.documentElement;
    h.firstChild ? h.insertBefore(el, h.firstChild) : h.appendChild(el);
  }

  /* ── preconnect ──────────────────────────────────────────────────────── */
  function preconnect() {
    try {
      if (doc.querySelector('link[rel="preconnect"][href="' + CDN + '"]'))
        return;
      var l = doc.createElement("link");
      l.rel = "preconnect";
      l.href = CDN;
      l.crossOrigin = "anonymous";
      (doc.head || doc.documentElement).appendChild(l);
    } catch (e) {}
  }

  /* ── init ────────────────────────────────────────────────────────────── */
  function init() {
    injectCSS();
    if (!REMOTE_FETCH) {
      log(
        "remote SVG fetch disabled on",
        win.location.hostname || "this origin",
      );
      return;
    }
    preconnect();
    upgradeAllIcons(doc);

    /* Watch DOM: rAF-batched dedup-Set, early isIconEl filter (FA6/Shoelace 2026 pattern).
     * One rAF frame per burst → 1 flush, dedup via Set, no full-doc querySelectorAll,
     * no re-entrancy. Initial scan (upgradeAllIcons above) is unaffected. */
    var _pend = new Set();
    var _raf  = 0;
    function _flush() {
      _raf = 0;
      _pend.forEach(function (e) { upgradeIcon(e); });
      _pend.clear();
      // One ST re-measure per DOM mutation burst (layout shift from new nodes, not per icon)
      if (win.ScrollTrigger) win.ScrollTrigger.refresh();
    }
    function _sched() { if (!_raf) _raf = win.requestAnimationFrame(_flush); }
    var mo = new MutationObserver(function (muts) {
      for (var i = 0; i < muts.length; i++) {
        var m = muts[i];
        if (m.type === "attributes") {
          if (isIconEl(m.target)) _pend.add(m.target);
        } else {
          var added = m.addedNodes;
          if (!added) continue;
          for (var j = 0; j < added.length; j++) {
            var n = added[j];
            if (n.nodeType !== 1) continue;
            if (isIconEl(n)) _pend.add(n);
            if (n.querySelectorAll) {
              var sub = n.querySelectorAll(SELECTOR);
              for (var k = 0; k < sub.length; k++) _pend.add(sub[k]);
            }
          }
        }
      }
      if (_pend.size) _sched();
    });
    mo.observe(doc.body || doc.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: ["class", "data-icon"],
    });

    /* Re-scan on bfcache restore */
    win.addEventListener("pageshow", function (e) {
      if (e.persisted) upgradeAllIcons(doc);
    });

    log("Apollo Icons runtime ready — v1.0.3");
  }

  if (doc.readyState === "loading") {
    doc.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }

  /* ── Public API ──────────────────────────────────────────────────────── */
  win.apolloIcons = {
    version: "1.0.3",
    remoteFetch: REMOTE_FETCH,
    rescan: REMOTE_FETCH
      ? upgradeAllIcons
      : function () {} /* upgradeAllIcons(root?)  */,
    iconUrl: iconUrl /* iconUrl("home-s")       */,
    normalize: normalize /* normalize("ri-home-fill") */,
  };
})("undefined" !== typeof window ? window : this);
